package com.campuslostfound.service;
import com.campuslostfound.db.DatabaseManager; import com.campuslostfound.exception.ValidationException; import com.campuslostfound.model.ClaimStatus; import java.sql.*; import java.util.*;
public class ClaimService {
 private final ItemService items; private final UserService users; public ClaimService(ItemService i,UserService u){items=i;users=u;}
 public int addClaim(int itemId,int claimantId,String message)throws SQLException,ValidationException{if(items.findById(itemId)==null)throw new ValidationException("Item not found.");if(!users.exists(claimantId))throw new ValidationException("Claimant does not exist.");if(message==null||message.isBlank())throw new ValidationException("Claim message is required.");try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO claims(item_id,claimant_id,message,status) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,itemId);p.setInt(2,claimantId);p.setString(3,message.trim());p.setString(4,"PENDING");p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);}}throw new SQLException("Could not create claim.");}
 public List<String> getClaims()throws SQLException{List<String>a=new ArrayList<>();String q="SELECT c.id,c.item_id,c.claimant_id,c.message,c.status,u.name FROM claims c JOIN users u ON c.claimant_id=u.id ORDER BY c.id DESC";try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())a.add("#"+r.getInt(1)+" | Item #"+r.getInt(2)+" | Claimant: "+r.getString(6)+" | "+r.getString(5)+" | "+r.getString(4));}return a;}
 public void updateStatus(int claimId,ClaimStatus status)throws SQLException,ValidationException{int itemId=-1;try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement("SELECT item_id FROM claims WHERE id=?")){p.setInt(1,claimId);try(ResultSet r=p.executeQuery()){if(r.next())itemId=r.getInt(1);}}if(itemId<0)throw new ValidationException("Claim not found.");try(Connection c=DatabaseManager.getConnection();PreparedStatement p=c.prepareStatement("UPDATE claims SET status=? WHERE id=?")){p.setString(1,status.name());p.setInt(2,claimId);p.executeUpdate();}if(status==ClaimStatus.APPROVED)items.updateStatus(itemId,com.campuslostfound.model.ItemStatus.CLAIMED);}
}
